require_once __DIR__ . '/../config/config.php'; require_once __DIR__ . '/../core/Database.php'; require_once __DIR__ . '/../core/Auth.php'; require_once __DIR__ . '/../core/helpers.php'; require_once __DIR__ . '/../core/withu.php';
migrate_schema_if_needed();$auth=new Auth();$db=Database::getInstance();$body=withu_json_body();if($_SERVER['REQUEST_METHOD']!=='POST')withu_json_response(['success'=>false,'message'=>'请求方式错误'],405);withu_require_json_csrf($body);$type=trim((string)($body['target_type']??''));$id=(int)($body['target_id']??0);if(!in_array($type,['article','album','event'],true)||$id<=0)withu_json_response(['success'=>false,'message'=>'点赞对象不合法'],400);if($auth->isLoggedIn()){$actor='user:'.$auth->getCurrentUser()['id'];}else{if(session_status()===PHP_SESSION_NONE)session_start();if(empty($_SESSION['withu_guest_like_key']))$_SESSION['withu_guest_like_key']='guest:'.withu_token(24);$actor=$_SESSION['withu_guest_like_key'];}$old=$db->fetch('SELECT id FROM content_likes WHERE actor_key=:actor AND target_type=:type AND target_id=:target LIMIT 1',['actor'=>$actor,'type'=>$type,'target'=>$id]);if($old){$db->delete('content_likes','id=:id',['id'=>$old['id']]);$liked=false;}else{$db->insert('content_likes',['actor_key'=>$actor,'target_type'=>$type,'target_id'=>$id,'created_at'=>withu_now()]);$liked=true;}$count=$db->fetch('SELECT COUNT(*) c FROM content_likes WHERE target_type=:type AND target_id=:target',['type'=>$type,'target'=>$id]);withu_json_response(['success'=>true,'liked'=>$liked,'count'=>(int)($count['c']??0)]);
